/* 
 * ===================================================================
 * MOODTRAVEL RECOMMENDATION ENGINE
 * ===================================================================
 * 
 * This function uses the database above to generate recommendations
 * based on user answers. It creates a key from the combination and
 * looks up the corresponding recommendation.
 */
function getMoodTravelRecommendations(answers) {
  console.log('Getting recommendations for answers:', answers);
  
  // Create combination key from answers
  const experience = answers[1];
  const connection = answers[2];
  const pace = answers[3];
  
  const combinationKey = `${experience}-${connection}-${pace}`;
  console.log('Generated combination key:', combinationKey);
  
  // Look up recommendation in database
  let recommendation = moodTravelDatabase.recommendations[combinationKey];
  
  // If exact combination not found, try fallback combinations
  if (!recommendation) {
    console.log('Exact combination not found, trying fallbacks...');
    
    // Try without pace
    const fallbackKey1 = `${experience}-${connection}`;
    const fallbackOptions = Object.keys(moodTravelDatabase.recommendations).filter(key => key.startsWith(fallbackKey1));
    
    if (fallbackOptions.length > 0) {
      recommendation = moodTravelDatabase.recommendations[fallbackOptions[0]];
      console.log('Using fallback combination:', fallbackOptions[0]);
    } else {
      // Try with just experience
      const fallbackKey2 = experience;
      const experienceFallbacks = Object.keys(moodTravelDatabase.recommendations).filter(key => key.startsWith(fallbackKey2));
      
      if (experienceFallbacks.length > 0) {
        recommendation = moodTravelDatabase.recommendations[experienceFallbacks[0]];
        console.log('Using experience fallback:', experienceFallbacks[0]);
      } else {
        // Use default
        recommendation = moodTravelDatabase.recommendations['default-kerala'];
        console.log('Using default recommendation');
      }
    }
  }
  
  return recommendation;
}

