// Setup activity filter
function setupActivityFilter() {
  const activityFilter = document.getElementById('activity-filter');
  if (activityFilter) {
    activityFilter.addEventListener('change', function() {
      filterActivitiesByType(this.value);
    });
  }
}

function filterActivitiesByType(selectedType) {
  const activitiesGrid = document.getElementById('activities-grid');
  if (!activitiesGrid) return;
  
  const activityCards = activitiesGrid.querySelectorAll('.activity-card');
  
  activityCards.forEach(card => {
    const typeElement = card.querySelector('.activity-type');
    if (typeElement) {
      const cardType = typeElement.textContent.trim();
      if (selectedType === '' || cardType === selectedType) {
        card.style.display = 'flex';
      } else {
        card.style.display = 'none';
      }
    }
  });
}

