function updateGreenCoins() {
  const greenCoinsElements = [
    document.getElementById('green-coins'),
    document.getElementById('checkout-coins-balance')
  ];
  
  greenCoinsElements.forEach(element => {
    if (element) {
      element.textContent = appData.user.greenCoins;
    }
  });
}

function redeemItem(itemType, cost) {
  if (appData.user.greenCoins >= cost) {
    appData.user.greenCoins -= cost;
    updateGreenCoins();
    showConfirmation(`Successfully redeemed ${itemType}! You now have ${appData.user.greenCoins} green coins.`);
  } else {
    showConfirmation('Not enough green coins!', 'error');
  }
}

// Add activity to cart function
function addActivityToCart(activityName, price, location, greenCoins, type, duration) {
  const item = {
    id: Date.now(),
    type: 'activity',
    name: activityName,
    price: price,
    location: location,
    greenCoins: greenCoins,
    activityType: type,
    duration: duration
  };
  
  cart.push(item);
  updateCart();
  showConfirmation(`${activityName} added to cart!`);
}

// Green Coins Checkout Functions
function applyGreenCoins() {
  const coinsToUseInput = document.getElementById('coins-to-use');
  const coinsToUse = parseInt(coinsToUseInput.value) || 0;
  
  if (coinsToUse <= 0) {
    showConfirmation('Please enter a valid number of coins', 'error');
    return;
  }
  
  if (coinsToUse > appData.user.greenCoins) {
    showConfirmation('You don\'t have enough green coins!', 'error');
    return;
  }
  
  const currentTotal = cart.reduce((sum, item) => sum + item.price, 0);
  if (coinsToUse > currentTotal) {
    showConfirmation('Cannot use more coins than the bill amount!', 'error');
    return;
  }
  
  usedCoins = coinsToUse;
  appliedDiscount = coinsToUse;
  
  updateCheckoutSummary();
  showDiscountDisplay();
  coinsToUseInput.value = '';
  
  showConfirmation(`Applied discount of ₹${appliedDiscount} using ${usedCoins} green coins!`);
}

function removeDiscount() {
  usedCoins = 0;
  appliedDiscount = 0;
  updateCheckoutSummary();
  hideDiscountDisplay();
  showConfirmation('Discount removed!');
}

function showDiscountDisplay() {
  const discountDisplay = document.getElementById('discount-display');
  const coinsUsedElement = document.getElementById('coins-used');
  const discountAmountElement = document.getElementById('discount-amount');
  
  if (discountDisplay && coinsUsedElement && discountAmountElement) {
    coinsUsedElement.textContent = usedCoins;
    discountAmountElement.textContent = appliedDiscount;
    discountDisplay.style.display = 'block';
  }
}

function hideDiscountDisplay() {
  const discountDisplay = document.getElementById('discount-display');
  if (discountDisplay) {
    discountDisplay.style.display = 'none';
  }
}

function updateCheckoutSummary() {
  const checkoutSummary = document.getElementById('checkout-summary');
  if (!checkoutSummary) return;
  
  let total = cart.reduce((sum, item) => sum + item.price, 0);
  let summaryHTML = '<h3>Order Summary</h3>';
  
  cart.forEach(item => {
    summaryHTML += `
      <div style="display: flex; justify-content: space-between; margin-bottom: 10px;">
        <span>${item.name}</span>
        <span>₹${item.price.toLocaleString()}</span>
      </div>
    `;
  });
  
  summaryHTML += `
    <div style="border-top: 1px solid var(--color-border); padding-top: 10px; margin-top: 10px;">
      <div style="display: flex; justify-content: space-between; margin-bottom: 5px;">
        <span>Subtotal:</span>
        <span>₹${total.toLocaleString()}</span>
      </div>
  `;
  
  if (appliedDiscount > 0) {
    summaryHTML += `
      <div style="display: flex; justify-content: space-between; margin-bottom: 5px; color: var(--color-primary);">
        <span>Green Coins Discount:</span>
        <span>-₹${appliedDiscount.toLocaleString()}</span>
      </div>
    `;
    total -= appliedDiscount;
  }
  
  summaryHTML += `
      <strong style="display: flex; justify-content: space-between;">
        <span>Total:</span>
        <span>₹${total.toLocaleString()}</span>
      </strong>
    </div>
  `;
  
  checkoutSummary.innerHTML = summaryHTML;
}

// Cart functionality
function addToCart(type, name, price, location = '') {
  const item = {
    id: Date.now(),
    type: type,
    name: name,
    price: price,
    location: location
  };
  
  cart.push(item);
  updateCart();
  showConfirmation(`${name} added to cart!`);
}

function removeFromCart(itemId) {
  cart = cart.filter(item => item.id !== itemId);
  updateCart();
  showConfirmation('Item removed from cart!');
}

function updateCart() {
  const cartItems = document.getElementById('cart-items');
  const cartTotal = document.getElementById('cart-total');
  const totalAmount = document.getElementById('total-amount');
  
  if (!cartItems) return;
  
  if (cart.length === 0) {
    cartItems.innerHTML = '<p class="empty-cart">Your cart is empty</p>';
    if (cartTotal) cartTotal.style.display = 'none';
    return;
  }
  
  let total = 0;
  cartItems.innerHTML = '';
  
  cart.forEach(item => {
    total += item.price;
    const cartItem = document.createElement('div');
    cartItem.className = 'cart-item';
    
    let itemDescription = item.type;
    if (item.location) itemDescription += ` - ${item.location}`;
    if (item.activityType) itemDescription += ` (${item.activityType})`;
    if (item.duration) itemDescription += ` - ${item.duration}`;
    
    cartItem.innerHTML = `
      <div class="cart-item-info">
        <h4>${item.name}</h4>
        <p>${itemDescription}</p>
        ${item.greenCoins ? `<small style="color: var(--color-primary);">Earn ${item.greenCoins} green coins</small>` : ''}
      </div>
      <div class="cart-item-actions">
        <div class="cart-item-price">${item.price === 0 ? 'FREE' : '₹' + item.price.toLocaleString()}</div>
        <button class="btn btn--sm btn--outline" onclick="removeFromCart(${item.id})">Remove</button>
      </div>
    `;
    cartItems.appendChild(cartItem);
  });
  
  if (totalAmount) totalAmount.textContent = total.toLocaleString();
  if (cartTotal) cartTotal.style.display = 'block';
}

// Booking functionality
function bookPackage(packageName, price) {
  addToCart('package', packageName, price);
}

function searchStays() {
  const location = document.getElementById('location').value;
  const checkin = document.getElementById('checkin').value;
  const checkout = document.getElementById('checkout').value;
  
  if (!location || !checkin || !checkout) {
    showConfirmation('Please fill in all booking details', 'error');
    return;
  }
  
  navigateToPage('ecostay');
  
  const matchingState = Object.keys(appData.ecoStays).find(state => 
    state.toLowerCase().includes(location.toLowerCase())
  );
  
  if (matchingState) {
    setTimeout(() => {
      const stayFilter = document.getElementById('state-filter-stay');
      if (stayFilter) {
        stayFilter.value = matchingState;
        displayEcoStays(matchingState);
      }
    }, 200);
  }
}

// Checkout functionality
function checkout() {
  if (cart.length === 0) {
    showConfirmation('Your cart is empty!', 'error');
    return;
  }
  
  usedCoins = 0;
  appliedDiscount = 0;
  hideDiscountDisplay();
  
  const modal = document.getElementById('checkout-modal');
  updateCheckoutSummary();
  updateGreenCoins();
  
  if (modal) modal.classList.add('show');
}

function closeCheckout() {
  const modal = document.getElementById('checkout-modal');
  if (modal) modal.classList.remove('show');
  
  usedCoins = 0;
  appliedDiscount = 0;
  hideDiscountDisplay();
}

function processPayment() {
  const cardNumber = document.getElementById('card-number').value;
  const expiry = document.getElementById('expiry').value;
  const cvv = document.getElementById('cvv').value;
  const cardholder = document.getElementById('cardholder').value;
  
  if (!cardNumber || !expiry || !cvv || !cardholder) {
    showConfirmation('Please fill in all payment details', 'error');
    return;
  }
  
  const originalTotal = cart.reduce((sum, item) => sum + item.price, 0);
  const finalTotal = originalTotal - appliedDiscount;
  
  const order = {
    id: Date.now(),
    items: [...cart],
    originalTotal: originalTotal,
    discount: appliedDiscount,
    coinsUsed: usedCoins,
    total: finalTotal,
    date: new Date().toLocaleDateString(),
    status: 'Confirmed'
  };
  
  if (usedCoins > 0) {
    appData.user.greenCoins -= usedCoins;
  }
  
  let totalEarnedCoins = 0;
  cart.forEach(item => {
    if (item.type === 'activity' && item.greenCoins) {
      totalEarnedCoins += item.greenCoins;
    }
  });
  
  orderHistory.push(order);
  currentBookings.push(...cart);
  cart = [];
  
  updateCart();
  updateCurrentBookings();
  updateOrderHistory();
  closeCheckout();
  
  appData.user.greenCoins += 50 + totalEarnedCoins;
  updateGreenCoins();
  
  let confirmationMessage = 'Payment successful! Your booking is confirmed.';
  if (usedCoins > 0) {
    confirmationMessage += ` You saved ₹${appliedDiscount} using ${usedCoins} green coins.`;
  }
  if (totalEarnedCoins > 0) {
    confirmationMessage += ` You earned ${totalEarnedCoins} green coins from activities!`;
  }
  confirmationMessage += ' You earned 50 green coins for choosing eco-friendly options!';
  
  showConfirmation(confirmationMessage);
  
  navigateToPage('explore');
}

function updateCurrentBookings() {
  const bookingsContainer = document.getElementById('current-bookings');
  if (!bookingsContainer) return;
  
  if (currentBookings.length === 0) {
    bookingsContainer.innerHTML = '<p class="no-bookings">No active bookings</p>';
    return;
  }
  
  bookingsContainer.innerHTML = '';
  
  currentBookings.forEach(booking => {
    const bookingCard = document.createElement('div');
    bookingCard.className = 'cart-item';
    
    let bookingDescription = booking.type;
    if (booking.location) bookingDescription += ` - ${booking.location}`;
    if (booking.activityType) bookingDescription += ` (${booking.activityType})`;
    if (booking.duration) bookingDescription += ` - ${booking.duration}`;
    
    bookingCard.innerHTML = `
      <div class="cart-item-info">
        <h4>${booking.name}</h4>
        <p>${bookingDescription}</p>
        <span class="status status--success">${booking.status || 'Active'}</span>
        ${booking.greenCoins ? `<small style="color: var(--color-primary);">Earned ${booking.greenCoins} green coins</small>` : ''}
      </div>
      <div class="cart-item-price">${booking.price === 0 ? 'FREE' : '₹' + booking.price.toLocaleString()}</div>
    `;
    bookingsContainer.appendChild(bookingCard);
  });
}

function updateOrderHistory() {
  const historyContainer = document.getElementById('order-history');
  if (!historyContainer) return;
  
  if (orderHistory.length === 0) {
    historyContainer.innerHTML = '<p class="no-orders">No previous orders</p>';
    return;
  }
  
  historyContainer.innerHTML = '';
  orderHistory.forEach(order => {
    const orderCard = document.createElement('div');
    orderCard.className = 'cart-item';
    orderCard.innerHTML = `
      <div class="cart-item-info">
        <h4>Order #${order.id}</h4>
        <p>${order.date} - ${order.items.length} items</p>
        ${order.coinsUsed > 0 ? `<p style="color: var(--color-primary); font-size: 12px;">Used ${order.coinsUsed} green coins (₹${order.discount} discount)</p>` : ''}
        <span class="status status--success">${order.status}</span>
      </div>
      <div class="cart-item-price">₹${order.total.toLocaleString()}</div>
    `;
    historyContainer.appendChild(orderCard);
  });
}

// Profile functionality
function changeProfilePic() {
  const newPic = prompt('Enter new profile picture URL:');
  if (newPic) {
    const profileImage = document.getElementById('profile-image');
    if (profileImage) {
      profileImage.src = newPic;
      appData.user.profilePic = newPic;
      showConfirmation('Profile picture updated!');
    }
  }
}

function updateProfile() {
  const userNameInput = document.getElementById('user-name');
  if (userNameInput) {
    const newName = userNameInput.value;
    if (newName) {
      appData.user.name = newName;
      showConfirmation('Profile updated successfully!');
    }
  }
}

// Enhanced Chatbot functionality
function setupChatbot() {
  const chatInput = document.getElementById('chat-input');
  if (chatInput) {
    chatInput.addEventListener('keypress', function(e) {
      if (e.key === 'Enter') {
        sendMessage();
      }
    });
  }
}

function toggleChatbot() {
  const chatbotContainer = document.getElementById('chatbot-container');
  if (!chatbotContainer) return;
  
  chatbotOpen = !chatbotOpen;
  
  if (chatbotOpen) {
    chatbotContainer.classList.add('show');
    setTimeout(() => {
      const chatMessages = document.getElementById('chatbot-messages');
      if (chatMessages) {
        chatMessages.scrollTop = chatMessages.scrollHeight;
      }
    }, 100);
  } else {
    chatbotContainer.classList.remove('show');
  }
}

function sendMessage() {
  const chatInput = document.getElementById('chat-input');
  const chatMessages = document.getElementById('chatbot-messages');
  
  if (!chatInput || !chatMessages) return;
  
  const message = chatInput.value.trim();
  
  if (!message) return;
  
  const userMessage = document.createElement('div');
  userMessage.className = 'user-message';
  userMessage.textContent = message;
  chatMessages.appendChild(userMessage);
  
  chatMessages.scrollTop = chatMessages.scrollHeight;
  
  setTimeout(() => {
    const botMessage = document.createElement('div');
    botMessage.className = 'bot-message';
    
    const response = processConversation(message);
    botMessage.innerHTML = response;
    
    chatMessages.appendChild(botMessage);
    chatMessages.scrollTop = chatMessages.scrollHeight;
    
    setupChatInteractions(botMessage);
  }, 700);
  
  chatInput.value = '';
}

function processConversation(message) {
  const lowerMessage = message.toLowerCase();
  
  if (chatbotState.activityFlow.step === 'waiting_for_type') {
    const activityTypes = ['adventure', 'nature', 'sustainability', 'wellness', 'cultural'];
    const selectedType = activityTypes.find(type => lowerMessage.includes(type));
    
    if (selectedType) {
      chatbotState.activityFlow.selectedType = selectedType.charAt(0).toUpperCase() + selectedType.slice(1);
      chatbotState.activityFlow.step = 'waiting_for_paid_filter';
      return `Great choice! Are you looking for <strong>paid activities</strong> or <strong>free activities</strong>? You can also say "all" or "both" to see all options.`;
    } else {
      return "I didn't catch that. Please choose from: <strong>Adventure</strong>, <strong>Nature</strong>, <strong>Sustainability</strong>, <strong>Wellness</strong> or <strong>Cultural</strong> activities.";
    }
  }
  
  if (chatbotState.activityFlow.step === 'waiting_for_paid_filter') {
    let paidFilter = null;
    if (lowerMessage.includes('paid') && !lowerMessage.includes('free')) {
      paidFilter = 'paid';
    } else if (lowerMessage.includes('free') && !lowerMessage.includes('paid')) {
      paidFilter = 'free';
    } else if (lowerMessage.includes('all') || lowerMessage.includes('both') || (lowerMessage.includes('paid') && lowerMessage.includes('free'))) {
      paidFilter = 'all';
    }
    
    if (paidFilter) {
      chatbotState.activityFlow.selectedPaidFilter = paidFilter;
      chatbotState.activityFlow.step = null;
      return generateCuratedActivityList(chatbotState.activityFlow.selectedType, paidFilter);
    } else {
      return "Please specify if you want <strong>paid</strong> activities, <strong>free</strong> activities, or <strong>all</strong> activities.";
    }
  }
  
  if (chatbotState.waitingFor) {
    if (chatbotState.waitingFor === 'state') {
      let state = findMatchingState(lowerMessage);
      if (state) {
        chatbotState.context.state = state;
        
        if (chatbotState.currentTopic === 'ecostay') {
          chatbotState.waitingFor = null;
          return generateStayListForState(state);
        } else if (chatbotState.currentTopic === 'ecobite') {
          chatbotState.waitingFor = null;
          return generateFoodListForState(state);
        } else if (chatbotState.currentTopic === 'handicrafts') {
          chatbotState.waitingFor = null;
          return generateHandicraftListForState(state);
        }
      } else {
        return "I'm sorry, I couldn't recognize that state. Please select from Kerala, Rajasthan, Maharashtra, Himachal Pradesh, Uttarakhand, or other Indian states.";
      }
    }
  }
  
  if (lowerMessage.includes('stay') || lowerMessage.includes('hotel') || lowerMessage.includes('accommodation') || lowerMessage.includes('ecostay')) {
    chatbotState.currentTopic = 'ecostay';
    chatbotState.waitingFor = 'state';
    return "Great! I can help you find eco-friendly stays. Which state in India are you interested in exploring? <br><br>Available states: <strong>Kerala</strong>, <strong>Rajasthan</strong>, <strong>Maharashtra</strong>, <strong>Himachal Pradesh</strong>, <strong>Uttarakhand</strong>, and more...";
  }
  
  if (lowerMessage.includes('food') || lowerMessage.includes('restaurant') || lowerMessage.includes('cuisine') || lowerMessage.includes('ecobite')) {
    chatbotState.currentTopic = 'ecobite';
    chatbotState.waitingFor = 'state';
    return "I'd be happy to recommend some delicious regional cuisines! Which state's food would you like to explore? <br><br>Available states: <strong>Kerala</strong>, <strong>Rajasthan</strong>, <strong>Maharashtra</strong>, <strong>Himachal Pradesh</strong>, <strong>Uttarakhand</strong>";
  }
  
  if (lowerMessage.includes('handicraft') || lowerMessage.includes('craft') || lowerMessage.includes('souvenir')) {
    chatbotState.currentTopic = 'handicrafts';
    chatbotState.waitingFor = 'state';
    return "India has beautiful traditional handicrafts! Which state's handicrafts are you interested in exploring? <br><br>Available states: <strong>Kerala</strong>, <strong>Rajasthan</strong>";
  }
  
  if (lowerMessage.includes('activity') || lowerMessage.includes('activities') || lowerMessage.includes('adventure') || lowerMessage.includes('trek') || lowerMessage.includes('what can i do') || lowerMessage.includes('things to do') || lowerMessage.includes('experiences') || (lowerMessage.includes('eco') && (lowerMessage.includes('activity') || lowerMessage.includes('activities')))) {
    chatbotState.activityFlow.step = 'waiting_for_type';
    return "Exciting! I can help you find the perfect eco-activities. What type of activity are you looking for?<br><br><strong>🏔️ Adventure</strong> - Jungle trekking, rock climbing, wildlife photography<br><strong>🌿 Nature</strong> - Bird watching, nature walks, butterfly tours<br><strong>♻️ Sustainability</strong> - Beach cleanups, conservation workshops, organic farming<br><strong>🧘 Wellness</strong> - Yoga retreats, meditation sessions, Ayurveda workshops<br><br>Just tell me which category interests you most!";
  }
  
  if (lowerMessage.includes('green coins') || lowerMessage.includes('points') || lowerMessage.includes('wallet') || lowerMessage.includes('coins')) {
    return `You currently have <strong>${appData.user.greenCoins}</strong> green coins! 🪙<br><br>You can earn more by:<br>• Completing activities (15-40 coins)<br>• Booking eco-friendly options (50 coins)<br>• Writing reviews (25 coins)<br><br>Redeem them for discounts and eco-friendly goodies!`;
  }
  
  if (lowerMessage.includes('hello') || lowerMessage.includes('hi') || lowerMessage.includes('hey')) {
    return "Hello! 👋 I'm your EcoLink assistant. I can help you find:<br>• <strong>Eco-stays</strong> - Sustainable accommodations<br>• <strong>Regional cuisines</strong> - Local food experiences<br>• <strong>Handicrafts</strong> - Traditional crafts<br>• <strong>Eco-activities</strong> - Adventure, nature, wellness & sustainability activities<br><br>What would you like to explore today?";
  }
  
  return "I can help you find eco-stays, regional foods, handicrafts, or eco-activities. What are you looking for? 🌱<br><br>Try saying:<br>• \"Show me eco-activities\"<br>• \"I want to book a stay\"<br>• \"Tell me about local food\"<br>• \"Show me handicrafts\"";
}

function generateCuratedActivityList(activityType, paidFilter) {
  const activities = appData.activities[activityType] || [];
  
  let filteredActivities = activities;
  if (paidFilter === 'paid') {
    filteredActivities = activities.filter(activity => activity.price > 0);
  } else if (paidFilter === 'free') {
    filteredActivities = activities.filter(activity => activity.price === 0);
  }
  
  if (filteredActivities.length === 0) {
    return `Sorry, I couldn't find any ${paidFilter} ${activityType.toLowerCase()} activities at the moment. Would you like to see other options?`;
  }
  
  let filterText = paidFilter === 'all' ? '' : `${paidFilter} `;
  let html = `<strong>🎯 Here are the best ${filterText}${activityType.toLowerCase()} activities for you:</strong><br><br>`;
  
  filteredActivities.forEach(activity => {
    html += `
      <div class="chat-recommendation-card">
        <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 8px;">
          <div style="font-weight: 600; color: var(--color-primary); font-size: 16px;">${activity.name}</div>
          <div style="font-weight: 700; color: var(--color-primary); font-size: 16px; background: rgba(50, 184, 198, 0.1); padding: 4px 8px; border-radius: 10px;">${activity.priceDisplay}</div>
        </div>
        <div style="font-size: 12px; color: var(--color-text-secondary); margin-bottom: 5px;">📍 ${activity.location} • ⏰ ${activity.duration}</div>
        <div style="font-size: 13px; margin-bottom: 10px; line-height: 1.4;">${activity.description}</div>
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px;">
          <div style="font-size: 12px; color: var(--color-primary); font-weight: 600; background: rgba(255, 215, 0, 0.1); padding: 2px 8px; border-radius: 8px;">🪙 +${activity.greenCoins} coins</div>
          <div style="font-size: 11px; color: var(--color-text-muted); text-transform: uppercase; font-weight: 600; padding: 2px 6px; background: rgba(94, 130, 153, 0.1); border-radius: 6px;">${activityType}</div>
        </div>
        <button class="btn btn--sm btn--primary chat-activity-btn" data-name="${activity.name}" data-price="${activity.price}" data-location="${activity.location}" data-coins="${activity.greenCoins}" data-type="${activityType}" data-duration="${activity.duration}">
          Add to Cart
        </button>
      </div>
    `;
  });
  
  html += `<br><small style="color: var(--color-text-secondary);">💡 <strong>Tip:</strong> Free activities still earn you green coins!</small>`;
  
  return html;
}

function findMatchingState(message) {
  const allStates = [...new Set([
    ...appData.states.map(s => s.name),
    ...Object.keys(appData.ecoStays),
    ...Object.keys(appData.handicrafts)
  ])];
  
  for (const state of allStates) {
    if (message.toLowerCase().includes(state.toLowerCase())) {
      return state;
    }
  }
  
  return null;
}

function generateStayListForState(state) {
  if (!appData.ecoStays[state] || appData.ecoStays[state].length === 0) {
    return `I'm sorry, we don't have any eco-stays listed in ${state} yet. Would you like to explore stays in another state?`;
  }
  
  let html = `<strong>🏨 Here are our eco-friendly stays in ${state}:</strong><br><br>`;
  
  appData.ecoStays[state].forEach(stay => {
    html += `
      <div class="chat-recommendation-card">
        <img src="${stay.image}" alt="${stay.name}" style="width: 100%; height: 120px; object-fit: cover; border-radius: 8px; margin-bottom: 10px;">
        <div style="font-weight: 600; color: var(--color-primary); margin-bottom: 5px;">${stay.name}</div>
        <div style="font-size: 12px; color: var(--color-text-secondary); margin-bottom: 5px;">📍 ${stay.location}</div>
        <div style="font-weight: 600; margin-bottom: 8px;">₹${stay.price.toLocaleString()}/night</div>
        <div style="font-size: 12px; margin-bottom: 10px;">⭐ ${stay.rating} Rating</div>
        <div style="font-size: 12px; margin-bottom: 10px;">
          ${stay.facilities.slice(0, 3).map(facility => `<span style="background: rgba(50, 184, 198, 0.1); color: var(--color-primary); padding: 2px 6px; border-radius: 8px; margin-right: 4px; font-size: 11px;">${facility}</span>`).join('')}
        </div>
        <button class="btn btn--sm btn--primary chat-book-btn" data-type="ecostay" data-name="${stay.name}" data-price="${stay.price}" data-location="${stay.location}">
          Add to Cart
        </button>
      </div>
    `;
  });
  
  return html;
}

function generateFoodListForState(state) {
  const stateData = appData.states.find(s => s.name === state);
  if (!stateData || !stateData.foods.length) {
    return `I'm sorry, we don't have any regional cuisines listed for ${state} yet. Would you like to explore food from another state?`;
  }
  
  let html = `<strong>🍽️ Delicious cuisines from ${state}:</strong><br><br>`;
  
  stateData.foods.forEach(food => {
    html += `
      <div class="chat-recommendation-card">
        <div style="font-weight: 600; color: var(--color-primary); margin-bottom: 5px;">${food.name}</div>
        <div style="font-size: 12px; margin-bottom: 10px;">${food.description}</div>
        <div style="font-size: 12px; margin-bottom: 10px;"><strong>🏪 Top places to try:</strong></div>
        ${food.restaurants.map(restaurant => `
          <div style="margin-bottom: 5px; padding: 8px; background: rgba(50, 184, 198, 0.1); border-radius: 5px;">
            <strong>${restaurant.name}</strong> - ${restaurant.rating} ⭐<br>
            <small style="color: var(--color-primary); font-weight: 600;">${restaurant.price}</small> | <small>${restaurant.phone}</small>
          </div>
        `).join('')}
      </div>
    `;
  });
  
  return html;
}

function generateHandicraftListForState(state) {
  if (!appData.handicrafts[state] || appData.handicrafts[state].length === 0) {
    return `I'm sorry, we don't have any handicrafts listed for ${state} yet. Would you like to explore crafts from another state?`;
  }
  
  let html = `<strong>🎨 Beautiful handicrafts from ${state}:</strong><br><br>`;
  
  appData.handicrafts[state].forEach(craft => {
    html += `
      <div class="chat-recommendation-card">
        <img src="${craft.image}" alt="${craft.name}" style="width: 100%; height: 120px; object-fit: cover; border-radius: 8px; margin-bottom: 10px;">
        <div style="font-weight: 600; color: var(--color-primary); margin-bottom: 5px;">${craft.name}</div>
        <div style="font-size: 12px; color: var(--color-text-secondary); margin-bottom: 5px;">🧵 Materials: ${craft.materials}</div>
        <div style="font-weight: 600; margin-bottom: 8px;">₹${craft.price.toLocaleString()}</div>
        <div style="font-size: 12px; margin-bottom: 10px;">${craft.description}</div>
        <button class="btn btn--sm btn--primary chat-book-btn" data-type="handicraft" data-name="${craft.name}" data-price="${craft.price}">
          Add to Cart
        </button>
      </div>
    `;
  });
  
  return html;
}

function setupChatInteractions(botMessage) {
  const bookButtons = botMessage.querySelectorAll('.chat-book-btn');
  bookButtons.forEach(button => {
    button.addEventListener('click', function() {
      const type = this.getAttribute('data-type');
      const name = this.getAttribute('data-name');
      const price = parseInt(this.getAttribute('data-price'));
      const location = this.getAttribute('data-location') || '';
      
      addToCart(type, name, price, location);
      
      const confirmMessage = document.createElement('div');
      confirmMessage.className = 'bot-message';
      confirmMessage.innerHTML = `✅ <strong>${name}</strong> has been added to your cart!`;
      const chatMessages = document.getElementById('chatbot-messages');
      chatMessages.appendChild(confirmMessage);
      chatMessages.scrollTop = chatMessages.scrollHeight;
    });
  });
  
  const activityButtons = botMessage.querySelectorAll('.chat-activity-btn');
  activityButtons.forEach(button => {
    button.addEventListener('click', function() {
      const name = this.getAttribute('data-name');
      const price = parseInt(this.getAttribute('data-price'));
      const location = this.getAttribute('data-location');
      const coins = parseInt(this.getAttribute('data-coins'));
      const type = this.getAttribute('data-type');
      const duration = this.getAttribute('data-duration');
      
      addActivityToCart(name, price, location, coins, type, duration);
      
      const confirmMessage = document.createElement('div');
      confirmMessage.className = 'bot-message';
      confirmMessage.innerHTML = `✅ <strong>${name}</strong> has been added to your cart! You'll earn ${coins} green coins when you complete this activity.`;
      const chatMessages = document.getElementById('chatbot-messages');
      chatMessages.appendChild(confirmMessage);
      chatMessages.scrollTop = chatMessages.scrollHeight;
    });
  });
}

// Enhanced Speech Recognition functionality
function setupSpeechRecognition() {
  const micButton = document.getElementById('mic-button');
  if (!micButton) return;
  
  if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
    micButton.style.display = 'none';
    console.log('Speech recognition not supported in this browser');
    return;
  }
  
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  
  try {
    speechRecognition = new SpeechRecognition();
    speechRecognition.continuous = false;
    speechRecognition.interimResults = false;
    speechRecognition.lang = 'en-US';
    
    micButton.addEventListener('click', function() {
      if (chatbotState.isListening) {
        speechRecognition.stop();
        chatbotState.isListening = false;
        micButton.classList.remove('listening');
      } else {
        try {
          speechRecognition.start();
          chatbotState.isListening = true;
          micButton.classList.add('listening');
          
          const chatMessages = document.getElementById('chatbot-messages');
          const listeningMessage = document.createElement('div');
          listeningMessage.className = 'bot-message';
          listeningMessage.id = 'listening-indicator';
          listeningMessage.innerHTML = '🎤 Listening... Please speak now';
          chatMessages.appendChild(listeningMessage);
          chatMessages.scrollTop = chatMessages.scrollHeight;
          
        } catch (error) {
          console.error('Speech recognition error:', error);
          chatbotState.isListening = false;
          micButton.classList.remove('listening');
          showConfirmation('Voice recognition failed. Please try again or type your message.', 'error');
        }
      }
    });
    
    speechRecognition.onresult = function(event) {
      const transcript = event.results[0][0].transcript;
      const chatInput = document.getElementById('chat-input');
      
      const listeningIndicator = document.getElementById('listening-indicator');
      if (listeningIndicator) {
        listeningIndicator.remove();
      }
      
      if (chatInput) {
        chatInput.value = transcript;
        sendMessage();
      }
    };
    
    speechRecognition.onend = function() {
      chatbotState.isListening = false;
      micButton.classList.remove('listening');
      
      const listeningIndicator = document.getElementById('listening-indicator');
      if (listeningIndicator) {
        listeningIndicator.remove();
      }
    };
    
    speechRecognition.onerror = function(event) {
      console.error('Speech recognition error:', event.error);
      chatbotState.isListening = false;
      micButton.classList.remove('listening');
      
      const listeningIndicator = document.getElementById('listening-indicator');
      if (listeningIndicator) {
        listeningIndicator.remove();
      }
      
      const errorMessage = document.createElement('div');
      errorMessage.className = 'bot-message';
      errorMessage.textContent = "I couldn't hear you clearly. Please try again or type your message.";
      const chatMessages = document.getElementById('chatbot-messages');
      chatMessages.appendChild(errorMessage);
      chatMessages.scrollTop = chatMessages.scrollHeight;
    };
  } catch (error) {
    console.error('Failed to initialize speech recognition:', error);
    micButton.style.display = 'none';
  }
}

// Confirmation Popup System
function showConfirmation(message, type = 'success') {
  const popup = document.getElementById('confirmation-popup');
  const popupMessage = document.querySelector('.popup-message');
  const popupIcon = document.querySelector('.popup-icon');
  
  if (popup && popupMessage && popupIcon) {
    popupMessage.textContent = message;
    popupIcon.textContent = type === 'error' ? '❌' : '✅';
    
    popup.classList.add('show');
    
    setTimeout(() => {
      popup.classList.remove('show');
    }, 3500);
  }
}

// Search functionality
function setupSearchFilters() {
  const searchInputs = [
    { id: 'search-stay', callback: filterStays },
    { id: 'search-craft', callback: filterCrafts },
    { id: 'search-activity', callback: filterActivities }
  ];
  
  searchInputs.forEach(input => {
    const element = document.getElementById(input.id);
    if (element) {
      element.addEventListener('input', input.callback);
    }
  });
}

function filterStays() {
  const searchInput = document.getElementById('search-stay');
  if (!searchInput) return;
  
  const searchTerm = searchInput.value.toLowerCase();
  const stayCards = document.querySelectorAll('#ecostay-grid .expandable-card');
  
  stayCards.forEach(card => {
    const title = card.querySelector('.card-title');
    const description = card.querySelector('.card-content p');
    
    if (title && description) {
      const titleText = title.textContent.toLowerCase();
      const descText = description.textContent.toLowerCase();
      
      if (titleText.includes(searchTerm) || descText.includes(searchTerm)) {
        card.style.display = 'block';
      } else {
        card.style.display = 'none';
      }
    }
  });
}

function filterCrafts() {
  const searchInput = document.getElementById('search-craft');
  if (!searchInput) return;
  
  const searchTerm = searchInput.value.toLowerCase();
  const craftCards = document.querySelectorAll('#handicrafts-grid .expandable-card');
  
  craftCards.forEach(card => {
    const title = card.querySelector('.card-title');
    const description = card.querySelector('.card-content p');
    
    if (title && description) {
      const titleText = title.textContent.toLowerCase();
      const descText = description.textContent.toLowerCase();
      
      if (titleText.includes(searchTerm) || descText.includes(searchTerm)) {
        card.style.display = 'block';
      } else {
        card.style.display = 'none';
      }
    }
  });
}

function filterActivities() {
  const searchInput = document.getElementById('search-activity');
  if (!searchInput) return;
  
  const searchTerm = searchInput.value.toLowerCase();
  const activityCards = document.querySelectorAll('#activities-grid .activity-card');
  
  activityCards.forEach(card => {
    const title = card.querySelector('.activity-title');
    const description = card.querySelector('.activity-description');
    
    if (title && description) {
      const titleText = title.textContent.toLowerCase();
      const descText = description.textContent.toLowerCase();
      
      if (titleText.includes(searchTerm) || descText.includes(searchTerm)) {
        card.style.display = 'flex';
      } else {
        card.style.display = 'none';
      }
    }
  });
}

